/// <summary>
/// CB790_DiscountClaim
/// Create new version of GUPDiscountClaimProcessDialog to call new class METGUPDiscountClaimProcess
/// </summary>
class METGUPDiscountClaimProcessDialog extends GUPDiscountClaimProcessDialog
{
    DialogField dlgInventSiteId;
    DialogField dlgClaimType;
    DialogField dlgNumDays;

    InventSiteId                inventSiteId;
    METClaimType                metClaimType;
    METNumDaysBeforeTodayDate   numDays;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        inventSiteId,
        metClaimType,
        numDays
    #endmacro
    

}

Method.Source:
/// <summary>
/// Replaced the std query by METGUPDiscountClaim to remove the inner join with RetailPeriodicDiscount as the table will not be loaded
/// </summary>
public void initQueryRun()
{
    queryRun = new QueryRun(queryStr(METGUPDiscountClaim));
}

    /// <summary>
    /// Call custom class METGUPDiscountClaimProcess so that claim fee is created from custom table instead of standard table
    /// </summary>
    public void run()
    {
        // Exclude manual claim type so they are not processed
        //this.excludeManualClaimType();

        // Update queryRun from parameters
        this.updateQueryRun();

        METGUPDiscountClaimProcess::processClaims(queryRun);
    }

/// <summary>
/// Construct method
/// </summary>
/// <returns>New instance of METGUPDiscountClaimProcessDialog</returns>
public static METGUPDiscountClaimProcessDialog construct()
{
    return new METGUPDiscountClaimProcessDialog();
}

/// <summary>
/// Class description
/// </summary>
/// <returns>Class description</returns>
public static ClassDescription description()
{
    return "@GlobalUnifiedPricing:ProcessDiscountClaim";
}

    /// <summary>
    /// Main method
    /// </summary>
    /// <param name = "_args">Arguments</param>
    public static void main(Args _args)
    {
        /*if (!GUPGlobalEnableFeatureHelper::validateAttributeBasedPricingEnabled())
        {
            return;
        }*/

        METGUPDiscountClaimProcessDialog gupDiscountClaimProcessDialog = METGUPDiscountClaimProcessDialog::construct();

        try
        {
            if (gupDiscountClaimProcessDialog.prompt())
            {
                gupDiscountClaimProcessDialog.runOperation();

                Common record = _args.record();
                if (record && FormDataUtil::getFormDataSource(record))
                {
                    FormDataSource dataSource = FormDataUtil::getFormDataSource(record);
                    dataSource.research();
                }
            }
        }
        catch (Exception::Error)
        {
            throw error("@SYS4081590");
        }
    }

    /// <summary>
    /// For end of prom, we want to make sure users are adding a filter on discount end date.
    /// Current issue with MS when recreating the range, findRange returns null
    /// </summary>
    /// <param name = "calledFrom">Called from object</param>
    /// <returns>true if validation successful; otherwise, false</returns>
    public boolean validate(Object calledFrom = null)
    {
        boolean ret;
    
        ret = super(calledFrom);
 
        // Validate selected claim type is not manual
        if (metClaimType == METClaimType::Manual)
        {
            ret = checkFailed("@MET:ManualDiscountClaimValidation");
        }

        return ret;
    }

    /// <summary>
    /// Update queryRun object based on batch job parameters
    /// </summary>
    void updateQueryRun()
    {
        QueryBuildDataSource qbds = queryRun.query().dataSourceTable(tableNum(GUPDiscountClaim));
        
        if (inventSiteId)
        {
            qbds.addRange(fieldNum(GUPDiscountClaim, METClaimType)).value(queryValue(inventSiteId));
        }

        // For end of Prom, select any discount claims where discount end date <= today - number of days
        if (metClaimType == METClaimType::EndOfPromPeriod)
        {
            qbds.addRange(fieldNum(GUPDiscountClaim, METDiscountEndDate)).value(SysQueryRangeUtil::lessThanDate(1 - numDays));
        }

        qbds.addRange(fieldNum(GUPDiscountClaim, METClaimType)).value(queryValue(metClaimType));
    }

    /// <summary>
    /// Creates dialog fields
    /// </summary>
    /// <returns><c>DialogRunbase</c> object</returns>
    public Object dialog()
    {    
        DialogRunbase dialog = super();

        dlgInventSiteId = dialog.addField(extendedTypeStr(InventSiteId));
        dlgInventSiteId.value(inventSiteId);

        dlgClaimType = dialog.addField(enumStr(METClaimType));
        dlgClaimType.value(metClaimType);

        dlgNumDays = dialog.addField(extendedTypeStr(METNumDaysBeforeTodayDate));
        dlgNumDays.value(numDays);

        return dialog;
    }

    /// <summary>
    /// Get values from dialog parameters
    /// </summary>
    /// <returns>true if able to get parameters value; otherwise, false</returns>
    public boolean getFromDialog()
    {
        boolean ret;
    
        ret = super();

        inventSiteId    = dlgInventSiteId.value();
        metClaimType    = dlgClaimType.value();
        numDays         = dlgNumDays.value();
    
        return ret;
    }

/// <summary>
/// Do not show records to include
/// </summary>
/// <returns>Forced to false</returns>
public boolean showQueryValues()
{    
    return false;
}

/// <summary>
/// pack current parameters
/// </summary>
/// <returns>Container of parameters</returns>
public container pack()
{
    return [#CurrentVersion, #CurrentList];
}

    /// <summary>
    /// unpack parameters
    /// </summary>
    /// <param name = "_packedClass">Packed class</param>
    /// <returns>true if unpack successful; otherwise, false</returns>
    public boolean unpack(container _packedClass)
    {
        Version version = runbase::getVersion(_packedClass);
        switch (version)
        {
            case #CurrentVersion:
                [version, #CurrentList] = _packedClass;
                break;
            default:
                return false;
        }

        return true;
    }
